-- ==============================================================================
-- 👑 V9: COMPLETE MASTER MENU TAXONOMY, 2-TIER RBAC, MAKER-CHECKER & ONBOARDING
-- ==============================================================================

-- 1. Bảng Danh mục Menu Gốc Toàn Hệ Thống (Master Menus)
CREATE TABLE IF NOT EXISTS `master_menus` (
    `code` VARCHAR(80) PRIMARY KEY,
    `parent_code` VARCHAR(80) NULL,
    `portal_type` ENUM('SUPERADMIN', 'CORP', 'CONSUMER', 'SYSTEM') NOT NULL,
    `route_path` VARCHAR(150) NULL,
    `icon` VARCHAR(60) NULL,
    `sort_order` INT NOT NULL DEFAULT 0,
    `is_active` BOOLEAN NOT NULL DEFAULT TRUE,
    `is_leaf` BOOLEAN NOT NULL DEFAULT TRUE,
    `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX `idx_menu_parent` (`parent_code`),
    INDEX `idx_menu_portal` (`portal_type`),
    CONSTRAINT `fk_mm_parent` FOREIGN KEY (`parent_code`) REFERENCES `master_menus` (`code`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. Bảng Đa Ngôn Ngữ Cho Menu (Menu i18n)
CREATE TABLE IF NOT EXISTS `menu_i18n` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `menu_code` VARCHAR(80) NOT NULL,
    `lang` VARCHAR(10) NOT NULL DEFAULT 'vi',
    `title` VARCHAR(200) NOT NULL,
    `description` VARCHAR(500) NULL,
    `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY `uk_menu_lang` (`menu_code`, `lang`),
    CONSTRAINT `fk_mi18n_menu` FOREIGN KEY (`menu_code`) REFERENCES `master_menus` (`code`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. Bảng Danh mục Quyền Vi Mô Theo Menu Code (Master Permissions)
CREATE TABLE IF NOT EXISTS `master_permissions` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `menu_code` VARCHAR(80) NOT NULL,
    `action` ENUM('READ', 'WRITE', 'APPROVE', 'EXPORT', 'DELETE', 'EXECUTE') NOT NULL,
    `permission_code` VARCHAR(100) NOT NULL UNIQUE,
    `description` VARCHAR(255) NULL,
    `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT `fk_mp_menu` FOREIGN KEY (`menu_code`) REFERENCES `master_menus` (`code`) ON DELETE CASCADE,
    INDEX `idx_mp_menu` (`menu_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 4. Bảng Cấp Phát Menu Cho Tenant (Tenant Menus)
CREATE TABLE IF NOT EXISTS `tenant_menus` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `tenant_id` VARCHAR(50) NOT NULL,
    `menu_code` VARCHAR(80) NOT NULL,
    `is_enabled` BOOLEAN NOT NULL DEFAULT TRUE,
    `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY `uk_tenant_menu` (`tenant_id`, `menu_code`),
    CONSTRAINT `fk_tm_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_tm_menu` FOREIGN KEY (`menu_code`) REFERENCES `master_menus` (`code`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 5. Bảng Nhóm Vai Trò Nội Bộ Doanh Nghiệp (Tenant Roles)
CREATE TABLE IF NOT EXISTS `tenant_roles` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `tenant_id` VARCHAR(50) NOT NULL,
    `role_code` VARCHAR(50) NOT NULL,
    `role_name` VARCHAR(100) NOT NULL,
    `role_type` ENUM('CORP_ADMIN', 'MAKER', 'CHECKER', 'BRANCH_MANAGER', 'AUDITOR', 'STAFF', 'CUSTOMER') NOT NULL DEFAULT 'STAFF',
    `description` VARCHAR(255) NULL,
    `is_system_reserved` BOOLEAN NOT NULL DEFAULT FALSE,
    `is_active` BOOLEAN NOT NULL DEFAULT TRUE,
    `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY `uk_tenant_role` (`tenant_id`, `role_code`),
    CONSTRAINT `fk_tr_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 6. Bảng Phân Quyền Chi Tiết Cho Role Nội Bộ Của Tenant (Tenant Role Permissions)
CREATE TABLE IF NOT EXISTS `tenant_role_permissions` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `tenant_role_id` BIGINT NOT NULL,
    `permission_id` BIGINT NOT NULL,
    `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY `uk_trp` (`tenant_role_id`, `permission_id`),
    CONSTRAINT `fk_trp_role` FOREIGN KEY (`tenant_role_id`) REFERENCES `tenant_roles` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_trp_perm` FOREIGN KEY (`permission_id`) REFERENCES `master_permissions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 7. Bảng Gán Vai Trò Cho Nhân Viên Nội Bộ (Tenant User Roles)
CREATE TABLE IF NOT EXISTS `tenant_user_roles` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `tenant_id` VARCHAR(50) NOT NULL,
    `user_id` BIGINT NOT NULL,
    `tenant_role_id` BIGINT NOT NULL,
    `department` VARCHAR(100) NULL,
    `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY `uk_tur` (`tenant_id`, `user_id`, `tenant_role_id`),
    CONSTRAINT `fk_tur_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_tur_role` FOREIGN KEY (`tenant_role_id`) REFERENCES `tenant_roles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 8. Bảng Quản Lý Luồng Duyệt Phân Tách Trách Nhiệm (Maker - Checker Approval Center)
CREATE TABLE IF NOT EXISTS `approval_requests` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `tenant_id` VARCHAR(50) NOT NULL,
    `request_type` VARCHAR(50) NOT NULL,
    `menu_code` VARCHAR(80) NOT NULL,
    `entity_type` VARCHAR(50) NOT NULL,
    `entity_id` VARCHAR(100) NULL,
    `maker_user_id` BIGINT NOT NULL,
    `checker_user_id` BIGINT NULL,
    `status` ENUM('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED') NOT NULL DEFAULT 'PENDING',
    `proposed_payload` JSON NOT NULL,
    `rejection_reason` VARCHAR(500) NULL,
    `maker_note` VARCHAR(255) NULL,
    `checker_note` VARCHAR(255) NULL,
    `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `reviewed_at` TIMESTAMP NULL,
    INDEX `idx_appr_tenant_status` (`tenant_id`, `status`),
    INDEX `idx_appr_maker` (`maker_user_id`),
    INDEX `idx_appr_checker` (`checker_user_id`),
    CONSTRAINT `fk_ar_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_ar_maker` FOREIGN KEY (`maker_user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_ar_checker` FOREIGN KEY (`checker_user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_ar_menu` FOREIGN KEY (`menu_code`) REFERENCES `master_menus` (`code`) ON DELETE CASCADE,
    CONSTRAINT `chk_sod_maker_checker` CHECK (`maker_user_id` <> `checker_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 9. Bảng Lịch Sử Nhật Ký Phê Duyệt Bất Biến (Approval Audit History)
CREATE TABLE IF NOT EXISTS `approval_history` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `request_id` BIGINT NOT NULL,
    `action` ENUM('SUBMITTED', 'APPROVED', 'REJECTED', 'CANCELLED') NOT NULL,
    `actor_id` BIGINT NOT NULL,
    `actor_role` VARCHAR(50) NOT NULL,
    `comment` VARCHAR(500) NULL,
    `snapshot_payload` JSON NULL,
    `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT `fk_ah_request` FOREIGN KEY (`request_id`) REFERENCES `approval_requests` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_ah_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 10. Bảng Quy Trình 4 Cửa Ải Thẩm Định Khách Hàng Cá Nhân (4-Gate Customer Onboarding)
CREATE TABLE IF NOT EXISTS `customer_onboarding_gates` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `tenant_id` VARCHAR(50) NOT NULL,
    `user_id` BIGINT NOT NULL UNIQUE,
    `gate1_ekyc_status` ENUM('NOT_STARTED', 'PENDING', 'APPROVED', 'REJECTED') NOT NULL DEFAULT 'NOT_STARTED',
    `gate1_reviewer_id` BIGINT NULL,
    `gate1_reviewed_at` TIMESTAMP NULL,
    `gate1_notes` TEXT NULL,
    `gate2_role_tier_status` ENUM('NOT_STARTED', 'PENDING', 'APPROVED', 'REJECTED') NOT NULL DEFAULT 'NOT_STARTED',
    `assigned_tier` VARCHAR(30) NOT NULL DEFAULT 'TIER_1',
    `assigned_daily_limit` DECIMAL(18, 2) NOT NULL DEFAULT 5000000.00,
    `gate2_reviewer_id` BIGINT NULL,
    `gate2_reviewed_at` TIMESTAMP NULL,
    `gate3_wallet_provision_status` ENUM('NOT_STARTED', 'PENDING', 'PROVISIONED', 'FAILED') NOT NULL DEFAULT 'NOT_STARTED',
    `available_account_no` VARCHAR(50) NULL,
    `savings_account_no` VARCHAR(50) NULL,
    `gate3_provisioned_at` TIMESTAMP NULL,
    `gate4_device_binding_status` ENUM('NOT_STARTED', 'PENDING', 'BOUND', 'REJECTED') NOT NULL DEFAULT 'NOT_STARTED',
    `bound_device_serial` VARCHAR(100) NULL,
    `bound_device_model` VARCHAR(50) NULL,
    `bound_at` TIMESTAMP NULL,
    `overall_status` ENUM('IN_PROGRESS', 'COMPLETED', 'BLOCKED') NOT NULL DEFAULT 'IN_PROGRESS',
    `completed_at` TIMESTAMP NULL,
    `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT `fk_cog_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 11. Bảng Ma Trận Cấu Hình Toàn Cục & Ghi Đè 2 Tầng (2-Tier System Config Matrix)
CREATE TABLE IF NOT EXISTS `global_system_configs` (
    `config_key` VARCHAR(100) PRIMARY KEY,
    `category` VARCHAR(50) NOT NULL,
    `config_name` VARCHAR(150) NOT NULL,
    `data_type` ENUM('STRING', 'NUMBER', 'BOOLEAN', 'JSON') NOT NULL DEFAULT 'STRING',
    `value` TEXT NOT NULL,
    `min_value` DECIMAL(18, 4) NULL,
    `max_value` DECIMAL(18, 4) NULL,
    `is_tenant_overridable` BOOLEAN NOT NULL DEFAULT FALSE,
    `description` VARCHAR(255) NULL,
    `updated_by` BIGINT NULL,
    `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `tenant_config_overrides` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `tenant_id` VARCHAR(50) NOT NULL,
    `config_key` VARCHAR(100) NOT NULL,
    `override_value` TEXT NOT NULL,
    `is_active` BOOLEAN NOT NULL DEFAULT TRUE,
    `maker_id` BIGINT NULL,
    `checker_id` BIGINT NULL,
    `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY `uk_tenant_cfg` (`tenant_id`, `config_key`),
    CONSTRAINT `fk_tco_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_tco_key` FOREIGN KEY (`config_key`) REFERENCES `global_system_configs` (`config_key`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


