('SYS_FW_MPU6050_ISR', 'vi', 'Ngắt Phần cứng Nhận diện Rung lắc / Va đập MPU6050', 'Bắt ngắt phần cứng cực nhạy khi thiết bị bị nhấc lên, lật ngược hoặc va đập mạnh quá ngưỡng an toàn.'),
('SYS_FW_MPU6050_ISR', 'en', 'MPU6050 Accelerometer Impact Interrupt ISR', 'Bắt ngắt phần cứng cực nhạy khi thiết bị bị nhấc lên, lật ngược hoặc va đập mạnh quá ngưỡng an toàn.'),
('SYS_FW_MPU6050_ISR', 'zh', 'MPU6050加速度计撞击/倾斜中断服务程序', 'Bắt ngắt phần cứng cực nhạy khi thiết bị bị nhấc lên, lật ngược hoặc va đập mạnh quá ngưỡng an toàn.'),
('SYS_FW_NVS_OFFLINE_QUEUE', 'vi', 'Hàng đợi Giao dịch Ngoại tuyến Bộ nhớ Flash NVS', 'Lưu tạm dữ liệu thả tiền vào bộ nhớ bất biến khi mất mạng Wi-Fi và tự động gửi bù về máy chủ ngay khi có mạng trở lại.'),
('SYS_FW_NVS_OFFLINE_QUEUE', 'en', 'Non-Volatile Flash Memory (NVS) Offline Queue', 'Lưu tạm dữ liệu thả tiền vào bộ nhớ bất biến khi mất mạng Wi-Fi và tự động gửi bù về máy chủ ngay khi có mạng trở lại.'),
('SYS_FW_NVS_OFFLINE_QUEUE', 'zh', '非易失性闪存 (NVS) 离线交易队列', 'Lưu tạm dữ liệu thả tiền vào bộ nhớ bất biến khi mất mạng Wi-Fi và tự động gửi bù về máy chủ ngay khi có mạng trở lại.'),
('SYS_INFRA_DATASTORE', 'vi', 'Cụm Cơ sở Dữ liệu & Lưu trữ Phân tán', 'Cấu hình hạ tầng lưu trữ lõi đảm bảo chuẩn giao dịch tài chính ACID, bộ nhớ đệm tốc độ cao và lưu trữ tệp nhị phân.'),
('SYS_INFRA_DATASTORE', 'en', 'Distributed Datastores & Storage Clusters', 'Cấu hình hạ tầng lưu trữ lõi đảm bảo chuẩn giao dịch tài chính ACID, bộ nhớ đệm tốc độ cao và lưu trữ tệp nhị phân.'),
('SYS_INFRA_DATASTORE', 'zh', '分布式数据库与存储集群', 'Cấu hình hạ tầng lưu trữ lõi đảm bảo chuẩn giao dịch tài chính ACID, bộ nhớ đệm tốc độ cao và lưu trữ tệp nhị phân.'),
('SYS_INFRA_MYSQL_CLUSTER', 'vi', 'Cụm Cơ sở Dữ liệu MySQL Phân tách Đọc/Ghi', 'Phân bổ đọc ghi (Read-Write Split), bảo vệ bảng sổ cái kép bất biến và hỗ trợ phân vùng dữ liệu theo Tenant Schema.'),
('SYS_INFRA_MYSQL_CLUSTER', 'en', 'MySQL Primary-Replica & Galera Cluster', 'Phân bổ đọc ghi (Read-Write Split), bảo vệ bảng sổ cái kép bất biến và hỗ trợ phân vùng dữ liệu theo Tenant Schema.'),
('SYS_INFRA_MYSQL_CLUSTER', 'zh', 'MySQL读写分离主从与Galera集群', 'Phân bổ đọc ghi (Read-Write Split), bảo vệ bảng sổ cái kép bất biến và hỗ trợ phân vùng dữ liệu theo Tenant Schema.'),
('SYS_INFRA_REDIS_SENTINEL', 'vi', 'Cụm Redis Sentinel Bộ nhớ đệm & Blacklist', 'Cụm lưu trữ phiên đăng nhập, cây menu động và kiểm tra tức thời danh sách token bị thu hồi với độ trễ dưới 1ms.'),
('SYS_INFRA_REDIS_SENTINEL', 'en', 'Redis Sentinel Cache & Token Blacklist', 'Cụm lưu trữ phiên đăng nhập, cây menu động và kiểm tra tức thời danh sách token bị thu hồi với độ trễ dưới 1ms.'),
('SYS_INFRA_REDIS_SENTINEL', 'zh', 'Redis Sentinel高可用缓存与令牌黑名单', 'Cụm lưu trữ phiên đăng nhập, cây menu động và kiểm tra tức thời danh sách token bị thu hồi với độ trễ dưới 1ms.'),
('SYS_INFRA_KAFKA_BROKER', 'vi', 'Hạ tầng Hàng đợi Phân tán Apache Kafka', 'Tiếp nhận các sự kiện tài chính từ Transactional Outbox, điều phối các luồng xử lý bất đồng bộ quy mô lớn.'),
('SYS_INFRA_KAFKA_BROKER', 'en', 'Apache Kafka Distributed Event Streaming', 'Tiếp nhận các sự kiện tài chính từ Transactional Outbox, điều phối các luồng xử lý bất đồng bộ quy mô lớn.'),
('SYS_INFRA_KAFKA_BROKER', 'zh', 'Apache Kafka分布式流处理与事件中枢', 'Tiếp nhận các sự kiện tài chính từ Transactional Outbox, điều phối các luồng xử lý bất đồng bộ quy mô lớn.'),
('SYS_INFRA_MINIO_STORAGE', 'vi', 'Cụm Lưu trữ Nhị phân Kháng lỗi MinIO S3', 'Lưu trữ mã hóa ảnh eKYC CCCD, biên lai mua sắm OCR, tệp firmware .bin và các bản sao kê PDF có gắn chữ ký số.'),
('SYS_INFRA_MINIO_STORAGE', 'en', 'MinIO S3 Fault-Tolerant Object Storage', 'Lưu trữ mã hóa ảnh eKYC CCCD, biên lai mua sắm OCR, tệp firmware .bin và các bản sao kê PDF có gắn chữ ký số.'),
('SYS_INFRA_MINIO_STORAGE', 'zh', 'MinIO S3容错对象存储集群', 'Lưu trữ mã hóa ảnh eKYC CCCD, biên lai mua sắm OCR, tệp firmware .bin và các bản sao kê PDF có gắn chữ ký số.');
